def check_time_limit(m, n, t):
    complexities = [1, 2, n**4, n**3, n**2, n * log2(n), n]
    if t < 1 or t > 7:
        raise ValueError("Invalid value for t. It must be between 1 and 7 inclusive.")
    if n < 1 or n > 10**9:
        raise ValueError("Invalid value for n. It must be between 1 and 10^9 inclusive.")
    if m < 1 or m > 10**9:
        raise ValueError("Invalid value for m. It must be between 1 and 10^9 inclusive.")

    required_operations = complexities[t - 1]
    if required_operations <= m:
        return "AC"
    else:
        return "TLE"

